import deployedConfig from '../contracts/deployedAddress.json';
import artifact from '../contracts/PaymentLink.json';

// Resolves contract address from:
// 1. localStorage override (useful if user deploys or inputs address in UI)
// 2. Vite environment variable VITE_PAYMENT_LINK_ADDRESS
// 3. deployedAddress.json generated by npm run deploy
export function getContractAddress() {
  if (typeof window !== 'undefined') {
    const cached = localStorage.getItem('bot_paylink_address');
    if (cached && cached.startsWith('0x') && cached.length === 42) {
      return cached;
    }
  }

  const envAddress = import.meta.env.VITE_PAYMENT_LINK_ADDRESS;
  if (envAddress && envAddress.startsWith('0x') && envAddress.length === 42) {
    return envAddress;
  }

  if (deployedConfig.address && deployedConfig.address.startsWith('0x')) {
    return deployedConfig.address;
  }

  return '';
}

export function setCustomContractAddress(address) {
  if (typeof window !== 'undefined') {
    if (!address) {
      localStorage.removeItem('bot_paylink_address');
    } else {
      localStorage.setItem('bot_paylink_address', address.trim());
    }
  }
}

export const PAYMENT_LINK_ABI = artifact.abi;
export const RPC_URL = import.meta.env.VITE_RPC_URL || 'https://rpc.bohr.life';
export const EXPLORER_URL = 'https://scan.bohr.life';
export const CHAIN_ID = 968;
